<script setup>
import { ref, computed, onMounted } from 'vue';
import { api, send, session, isCoach } from './api';
import FoodBuilder from './FoodBuilder.vue';
const links=ref([]),email=ref(''),error=ref(''),message=ref(''),busy=ref(false),selected=ref(''),progress=ref(null),plans=ref([]),exercises=ref([]),title=ref(''),kind=ref('Workout'),entries=ref([]),exerciseId=ref(''),calculated=ref(null);
const students=computed(()=>links.value.filter(x=>x.coachId===session.user.id&&x.status==='Active'));
const selectedName=computed(()=>students.value.find(x=>x.studentId===selected.value)?.studentName);
async function load(){try{[links.value,exercises.value]=await Promise.all([api('/links'),api('/catalog/exercises')]);}catch(e){error.value=e.message;}}
async function moreLinks(){try{links.value.push(...await api('/links?before='+(links.value.at(-1)?.id||2147483647)));}catch(e){error.value=e.message;}}
async function morePlans(){try{plans.value.push(...await api('/plans?studentId='+encodeURIComponent(selected.value)+'&after='+(plans.value.at(-1)?.id||0)));}catch(e){error.value=e.message;}}
async function invite(){busy.value=true;error.value='';message.value='';try{await send('/links',{email:email.value});email.value='';message.value='Invitation appears in the student’s dashboard. No email was sent.';await load();}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function student(){progress.value=null;plans.value=[];error.value='';if(!selected.value)return;busy.value=true;try{[progress.value,plans.value]=await Promise.all([api('/progress?studentId='+encodeURIComponent(selected.value)),api('/plans?studentId='+encodeURIComponent(selected.value))]);}catch(e){error.value=e.message;}finally{busy.value=false;}}
function add(){if(exerciseId.value&&entries.value.length<30)entries.value.push({exerciseId:exerciseId.value,sets:3,reps:10,restSeconds:60});}
async function assign(){busy.value=true;error.value='';message.value='';try{await send('/plans',{studentId:selected.value,title:title.value,kind:kind.value,exercises:kind.value==='Workout'?entries.value:null,foods:kind.value==='Nutrition'?calculated.value?.portions:null});message.value='Plan assigned. A saved snapshot is now visible to your student.';title.value='';entries.value=[];await student();}catch(e){error.value=e.message;}finally{busy.value=false;}}
onMounted(()=>{if(isCoach())load();});
</script>
<template>
  <div v-if="!isCoach()" class="card"><h1>Coach access required.</h1><p>An administrator must approve your coaching account.</p></div>
  <template v-else>
    <div class="page-heading"><div><p class="eyebrow">SUPPORT THE PERSON BEHIND THE PROGRESS</p><h1>Your coaching desk<span class="lime-dot">.</span></h1><p>A focused workspace for your students and their next steps.</p></div><span class="tag">{{students.length}} ACTIVE STUDENTS</span></div>
    <p v-if="error" class="notice error" role="alert">{{error}}</p><p v-if="message" class="notice" role="status">{{message}}</p>
    <div class="two-column"><form class="card" @submit.prevent="invite"><h2>Invite a student</h2><p class="muted">They must register first. Their records stay private until they accept your invitation.</p><label>Student’s registered email<input v-model="email" type="email" required></label><button class="primary" :disabled="busy">Send in-app invitation →</button></form><section class="card"><h2>Choose a student</h2><label>Active relationships<select v-model="selected" @change="student"><option value="">Choose a student…</option><option v-for="s in students" :value="s.studentId" :key="s.id">{{s.studentName}}</option></select></label><div class="relationship" v-for="l in links.filter(x=>x.coachId===session.user.id&&x.status!=='Active')" :key="l.id"><span>{{l.studentName}}</span><span class="tag">{{l.status}}</span></div><button v-if="links.length&&links.length%100===0" type="button" class="text-button" @click="moreLinks">Load more students</button><p v-if="!students.length" class="hint">Accepted invitations will appear here.</p></section></div>
    <template v-if="selected&&progress"><section class="card"><div class="section-heading"><div><p class="eyebrow">{{selectedName}}</p><h2>Progress · last 90 days</h2></div><button class="secondary" :disabled="busy" @click="student">Refresh</button></div><div class="stat-grid"><div><span>Latest weight</span><h3>{{progress.measurements.at(-1)?.weightKg ?? '—'}} kg</h3></div><div><span>Workouts recorded</span><h3>{{progress.workouts.length}}</h3></div><div><span>Meal entries</span><h3>{{progress.meals.length}}</h3></div><div><span>Assigned plans</span><h3>{{plans.length}}</h3></div></div><details><summary>Measurements and food diary</summary><div class="table-scroll"><table><thead><tr><th>Date</th><th>Weight · kg</th><th>Waist · cm</th></tr></thead><tbody><tr v-for="m in progress.measurements" :key="m.id"><td>{{new Date(m.recordedAt).toLocaleDateString()}}</td><td>{{m.weightKg}}</td><td>{{m.waistCm ?? '—'}}</td></tr></tbody></table><table><thead><tr><th>Date</th><th>Meal</th><th>kcal</th><th>Protein · g</th></tr></thead><tbody><tr v-for="m in progress.meals" :key="m.id"><td>{{new Date(m.recordedAt).toLocaleDateString()}}</td><td>{{m.name}}</td><td>{{m.kcal}}</td><td>{{m.protein}}</td></tr></tbody></table></div></details></section>
      <form class="card" @submit.prevent="assign"><p class="eyebrow">DESIGNED AROUND YOUR STUDENT</p><h2>Assign a plan</h2><div class="field-row"><label>Plan title<input v-model="title" required maxlength="120" placeholder="e.g. Week 1 · Full body"></label><label>Plan type<select v-model="kind"><option>Workout</option><option>Nutrition</option></select></label></div>
        <template v-if="kind==='Workout'"><div class="search-row"><label>Exercise<select v-model="exerciseId"><option value="">Choose a movement…</option><option v-for="e in exercises" :value="e.id" :key="e.id">{{e.name}}</option></select></label><button class="secondary" type="button" @click="add" :disabled="!exerciseId||entries.length>=30">+ Add exercise</button></div><div v-for="(e,i) in entries" :key="i" class="workout-entry"><strong>{{exercises.find(x=>x.id===e.exerciseId)?.name}}</strong><label>Sets<input v-model.number="e.sets" type="number" min="1" max="10" required></label><label>Reps<input v-model.number="e.reps" type="number" min="1" max="100" required></label><label>Rest · sec<input v-model.number="e.restSeconds" type="number" min="0" max="600" required></label><button type="button" class="text-button" @click="entries.splice(i,1)">Remove</button></div></template>
        <template v-else><FoodBuilder @calculated="calculated=$event"/><p class="hint">A nutrition plan is a saved food/portion template. Assess allergies, preferences and clinical needs with your student before assigning it.</p></template>
        <button class="primary" :disabled="busy||!(kind==='Workout'?entries.length:calculated)">Assign to {{selectedName}} →</button><p class="hint">Saved plans are immutable. Assign a new version when revising a plan.</p>
      </form><section class="card"><h2>Assigned plans</h2><div v-for="p in plans" :key="p.id" class="relationship"><strong>{{p.title}}</strong><span class="tag">{{p.kind}}</span><span>{{new Date(p.createdAt).toLocaleDateString()}}</span></div><button v-if="plans.length&&plans.length%50===0" class="text-button" @click="morePlans">Load more plans</button><p v-if="!plans.length" class="muted">No plans assigned yet.</p></section>
    </template>
  </template>
</template>
